		if e != nil {
			return e
		}
		if version != len(r.Policies)+1 {
			return invalid("policy versions must be 1, 2, ... in publication order")
		}
		p.Terms.PolicyVersion = version
		r.Policies = append(r.Policies, p)
	}
	return nil
