type Closure struct {
	TableID string
	From    time.Time
	To      time.Time
	FromRaw string
	ToRaw   string
	PlanID  string
}

func (c Closure) overlaps(start, end time.Time) bool { return overlaps(c.From, c.To, start, end) }

